package com.example.auth.repository;

import com.example.auth.entity.Token;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

@Repository
public interface TokenRepository extends JpaRepository<Token, Long> {
    Optional<Token> findByTokenValue(String tokenValue);
    List<Token> findByUserId(String userId);
    List<Token> findByExpiresAtBeforeAndIsRevokedOrIsConsumed(LocalDateTime now, boolean revoked, boolean consumed);

    @Modifying
    @Query("UPDATE Token t SET t.isRevoked = true WHERE t.tokenValue = :tokenValue AND t.tokenType = 'REFRESH' AND t.isRevoked = false AND t.isConsumed = false AND t.expiresAt > :now")
    int revokeRefreshTokenIfValid(@Param("tokenValue") String tokenValue, @Param("now") LocalDateTime now);

    @Modifying
    @Query("UPDATE Token t SET t.isConsumed = true WHERE t.tokenValue = :tokenValue AND t.tokenType = 'ONETIME' AND t.isRevoked = false AND t.isConsumed = false AND t.expiresAt > :now")
    int consumeOneTimeTokenIfValid(@Param("tokenValue") String tokenValue, @Param("now") LocalDateTime now);

    @Modifying
    @Query("UPDATE Token t SET t.isRevoked = true WHERE t.userId = :userId")
    void revokeAllTokensForUser(@Param("userId") String userId);

    @Modifying
    @Query("DELETE FROM Token t WHERE (t.expiresAt < :now) OR t.isRevoked = true OR t.isConsumed = true")
    int deleteExpiredOrRevokedOrConsumed(@Param("now") LocalDateTime now);

    Optional<Token> findByTokenValueAndTokenTypeAndIsRevokedFalseAndIsConsumedFalseAndExpiresAtAfter(String tokenValue, String tokenType, LocalDateTime now);
}
