package com.example.auth.service;

import com.example.auth.dto.*;
import com.example.auth.entity.Token;
import com.example.auth.repository.TokenRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;

@Service
public class AuthService {

    private final TokenRepository tokenRepository;

    public AuthService(TokenRepository tokenRepository) {
        this.tokenRepository = tokenRepository;
    }

    private String generateToken() {
        return UUID.randomUUID().toString();
    }

    @Transactional
    public LoginResponse login(String username, String password) {
        String userId = username;
        LocalDateTime now = LocalDateTime.now();

        String accessTokenValue = generateToken();
        String refreshTokenValue = generateToken();
        String oneTimeTokenValue = generateToken();

        Token accessToken = new Token(accessTokenValue, userId, "ACCESS", now, now.plusMinutes(10));
        Token refreshToken = new Token(refreshTokenValue, userId, "REFRESH", now, now.plusHours(24));
        Token oneTimeToken = new Token(oneTimeTokenValue, userId, "ONETIME", now, now.plusMinutes(5));

        tokenRepository.save(accessToken);
        tokenRepository.save(refreshToken);
        tokenRepository.save(oneTimeToken);

        return new LoginResponse(accessTokenValue, oneTimeTokenValue);
    }

    public String getRefreshTokenValue(String cookieValue, String headerValue) {
        if (cookieValue != null && !cookieValue.isEmpty()) {
            return cookieValue;
        }
        if (headerValue != null && !headerValue.isEmpty()) {
            return headerValue;
        }
        return null;
    }

    @Transactional
    public RenewResponse renew(String refreshTokenValue) {
        if (refreshTokenValue == null || refreshTokenValue.isEmpty()) {
            throw new RuntimeException("Refresh token is missing");
        }

        LocalDateTime now = LocalDateTime.now();

        // Atomically revoke the old refresh token if valid
        int updated = tokenRepository.revokeRefreshTokenIfValid(refreshTokenValue, now);
        if (updated == 0) {
            throw new RuntimeException("Refresh token is invalid, expired, or already used");
        }

        // Find the revoked token to get user_id
        Token oldToken = tokenRepository.findByTokenValue(refreshTokenValue).orElseThrow();
        String userId = oldToken.getUserId();

        // Issue new tokens
        String newAccessTokenValue = generateToken();
        String newRefreshTokenValue = generateToken();

        Token newAccessToken = new Token(newAccessTokenValue, userId, "ACCESS", now, now.plusMinutes(10));
        Token newRefreshToken = new Token(newRefreshTokenValue, userId, "REFRESH", now, now.plusHours(24));

        tokenRepository.save(newAccessToken);
        tokenRepository.save(newRefreshToken);

        return new RenewResponse(newAccessTokenValue);
    }

    public RenewResponse renewWithRefreshToken(String refreshTokenValue) {
        return renew(refreshTokenValue);
    }

    public String getNewRefreshTokenValue(String refreshTokenValue) {
        // We need a different approach - return the new refresh token value
        // This is handled differently in the controller
        return null;
    }

    @Transactional
    public ValidateTokenResponse validateOneTimeToken(String tokenValue) {
        if (tokenValue == null || tokenValue.isEmpty()) {
            return new ValidateTokenResponse(false, "Token is missing");
        }

        LocalDateTime now = LocalDateTime.now();

        // Atomically consume the token if valid
        int updated = tokenRepository.consumeOneTimeTokenIfValid(tokenValue, now);
        if (updated == 0) {
            return new ValidateTokenResponse(false, "Token is invalid, expired, revoked, or already consumed");
        }

        return new ValidateTokenResponse(true, "Token is valid and has been consumed");
    }

    @Transactional
    public LogoutResponse logout(String accessTokenValue) {
        if (accessTokenValue == null || accessTokenValue.isEmpty()) {
            throw new RuntimeException("Access token is missing");
        }

        LocalDateTime now = LocalDateTime.now();
        Token token = tokenRepository.findByTokenValueAndTokenTypeAndIsRevokedFalseAndIsConsumedFalseAndExpiresAtAfter(
                accessTokenValue, "ACCESS", now).orElse(null);

        if (token == null) {
            throw new RuntimeException("Access token is invalid");
        }

        String userId = token.getUserId();
        tokenRepository.revokeAllTokensForUser(userId);

        return new LogoutResponse("Logged out successfully");
    }
}
