package com.example.auth.controller;

import com.example.auth.dto.*;
import com.example.auth.service.AuthService;
import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request, HttpServletResponse response) {
        if (request.getUsername() == null || request.getUsername().isEmpty() ||
            request.getPassword() == null || request.getPassword().isEmpty()) {
            return ResponseEntity.badRequest().body(Map.of("error", "Username and password are required"));
        }

        LoginResponse loginResponse = authService.login(request.getUsername(), request.getPassword());

        Cookie refreshTokenCookie = new Cookie("refreshToken", loginResponse.getRefreshToken());
        refreshTokenCookie.setHttpOnly(true);
        refreshTokenCookie.setMaxAge(86400);
        refreshTokenCookie.setPath("/");
        response.addCookie(refreshTokenCookie);

        // Return only accessToken and oneTimeToken in JSON
        return ResponseEntity.ok(new LoginResponse(loginResponse.getAccessToken(), loginResponse.getOneTimeToken(), null));
    }

    @PostMapping("/renew")
    public ResponseEntity<?> renew(@CookieValue(value = "refreshToken", required = false) String cookieToken,
                                    @RequestHeader(value = "refreshToken", required = false) String headerToken,
                                    HttpServletResponse response) {
        String refreshTokenValue = authService.getRefreshTokenValue(cookieToken, headerToken);

        try {
            AuthService.RenewResult result = authService.renew(refreshTokenValue);

            Cookie refreshTokenCookie = new Cookie("refreshToken", result.refreshToken());
            refreshTokenCookie.setHttpOnly(true);
            refreshTokenCookie.setMaxAge(86400);
            refreshTokenCookie.setPath("/");
            response.addCookie(refreshTokenCookie);

            return ResponseEntity.ok(new RenewResponse(result.accessToken()));
        } catch (RuntimeException e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error", e.getMessage()));
        }
    }

    @PostMapping("/validate-token")
    public ResponseEntity<ValidateTokenResponse> validateToken(@RequestBody ValidateTokenRequest request) {
        ValidateTokenResponse response = authService.validateOneTimeToken(request.getToken());
        if (response.isValid()) {
            return ResponseEntity.ok(response);
        } else {
            return ResponseEntity.status(HttpStatus.CONFLICT).body(response);
        }
    }

    @PostMapping("/logout")
    public ResponseEntity<?> logout(@RequestHeader(value = "Authorization", required = false) String authHeader) {
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error", "Access token is missing"));
        }

        String accessTokenValue = authHeader.substring(7);
        try {
            LogoutResponse response = authService.logout(accessTokenValue);
            return ResponseEntity.ok(response);
        } catch (RuntimeException e) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error", e.getMessage()));
        }
    }
}
EOF"}

